fn _csv_header(t: _CsvTable) std.ArrayList([]const u8) {
    var _r: std.ArrayList([]const u8) = .empty;
    if (t.rows.len > 0) for (t.rows[0]) |f| _r.append(std.heap.page_allocator, f) catch {};
